INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=18850&keyref=6007684', '3A0852', now(), 'Official source captured 2026-09-11. THB 6,920,000; 133 sq.wah; registered two-storey house and pool, four bedrooms/five bathrooms. East side 24 m but actual road frontage only 4 m. Later-divided sale plot outside original subdivision approval uses private roads titles 100619/20098; no registered easement confirmation. Nineteen source photos dated 2022-03-16 and 2024-02-28; pool operability unconfirmed. Navigation/map agree. All-status duplicate search no matches.') ;
